<?php
namespace App\Services;use App\Models\{ComparisonRun,ProjectProfile,Survey};use Carbon\CarbonInterface;
class ReportSnapshotService{public function build(?Survey $survey,?ComparisonRun $comparison,CarbonInterface $from,CarbonInterface $to):array{$profile=ProjectProfile::where('is_active',true)->with('institution')->first();$snapshot=['project'=>['institution'=>$profile?->institution?->name,'title'=>$profile?->project_title,'aim'=>$profile?->aim,'objectives'=>$profile?->objectives],'period'=>['from'=>$from->toIso8601String(),'to'=>$to->toIso8601String()],'methodology'=>['RSSI and performance measurements','IDW heat-map interpolation','AP load and channel utilisation','User-feedback correlation','Deterministic insight rules']];if($survey){$measurements=$survey->points()->with(['measurements'=>fn($q)=>$q->where('is_simulated',false)->whereBetween('captured_at',[$from,$to])])->get()->flatMap->measurements;$heatmap=$survey->heatmaps()->where('status','completed')->whereBetween('generated_at',[$from,$to])->latest('generated_at')->first();$insights=$survey->insights()->whereBetween('generated_at',[$from,$to])->get();$snapshot['survey']=['id'=>$survey->id,'name'=>$survey->name,'location'=>$survey->floor->building->name.' · '.$survey->floor->name,'floor_plan_version'=>$survey->floorPlan->version,'measurement_count'=>$measurements->count(),'coverage_percent'=>$heatmap?->coverage_percent,'estimated_area_percent'=>$heatmap?->estimated_area_percent,'source_point_count'=>$heatmap?->source_point_count,'median_rssi_dbm'=>$this->median($measurements->pluck('rssi_dbm')),'median_download_mbps'=>$this->median($measurements->pluck('download_mbps')),'median_latency_ms'=>$this->median($measurements->pluck('latency_ms')),'median_packet_loss_percent'=>$this->median($measurements->pluck('packet_loss_percent')),'provenance'=>$measurements->groupBy('source_type')->map->count()->all(),'insights'=>$insights->map(fn($i)=>['title'=>$i->title,'severity'=>$i->severity,'evidence'=>$i->evidence,'recommendation'=>$i->recommendation,'limitations'=>$i->limitations])->all()];}$snapshot['comparison']=$comparison?->only(['baseline_metrics','followup_metrics','changes','compatibility_checks','limitations']);return $snapshot;}private function median($c):?float{$c=$c->filter(fn($v)=>$v!==null)->map(fn($v)=>(float)$v)->sort()->values();if($c->isEmpty())return null;$n=$c->count();return round($n%2?$c[intdiv($n,2)]:($c[$n/2-1]+$c[$n/2])/2,3);}}
